architecture.h4_f:
msg = CBOR{v:1, texte, réponse_à, envoyé_at}
ct = AES-GCM-256-Encrypt(k, nonce, msg, aad=room_id)
POST /api/rooms/{id}/messages {texte chiffré : hex(ct), nonce : hex}

cryptoWire.h1_f:
pt = CBOR{v:1, texte, réponse_à ?, identifiant_fil ?, mentions ?, envoyé_at}
ct = AES-GCM-256-Encrypt(room_key, nonce, pt, aad=hex(room_id))
fil = CBOR{
  v : 1,
  texte chiffré : hex(ct), // longueur variable
  occasionnel : hex(12 B),
  pseudo_expéditeur : hex(16 B),
  envoyé_à : unix_ms
}

cryptoWire.h5_f:
extérieur = CBOR{
  noeud_source : hex32,
  utilisateur_cible : int64,
  inner_ciphertext : octets,
  inner_nonce : octets,
  envoyé_à : unix_ms
}
sig = Ed25519-Sign(source_priv, externe)
POST /federation/deliver { enveloppe : externe, sig : hex64 }

auth.h1_f:
POST /api/authentification/registre
  { nom d'utilisateur, mot de passe, x25519_public_key, display_name, téléphone ?, email ?, avatar_emoji }

Réponse 201 créée :
  { access_token, rafraîchissement_token, user_id, nom d'utilisateur, ... }

auth.h3_f:
Charge utile access_token :
  { sous : user_id, jti : device_id, typ : "access", exp : now + 15min }
Charge utile actualiser_token :
  { sous : user_id, jti : device_id, typ : "refresh", exp : now + 30d }

HS256-signé avec le secret de 64 octets du nœud de .env

auth.h4_f:
register_begin() : défi = rand(32)
                    options = { rp.id, user.id, pubKeyCredParams, défi }
                    options de retour

register_finish(attestation) :
  vérifier l'attestation par rapport à TPM / racine Secure Enclave CA
  stocker { credential_id, public_key, compteur : 0 }

auth.h7_f:
POST /api/authentification/qr/begin
  → { occasionnel : hexadécimal 128 bits, ttl : 60 }
QR charge utile = { nonce, user_id, serveur : "https://node.example" }

POST /api/authentication/qr/verify { occasionnel }
  → nouvel appareil enregistré ; Les JWT sont revenus.

rooms.h6_f:
sender_pseudo = HMAC-SHA256(room_pseudo_salt, sender_id)[:16] // 32 hex
texte chiffré = AES-GCM-Encrypt(room_key, nonce, CBOR_payload, aad=room_id)

Trame de diffusion : { type:"m", room, msg:{id, ct, nonce, sender_pseudo, sent_at} }

files.h2_f:
init POST /api/files/resumable/init {nom de fichier, taille, chunk_size_hint}
            ← {upload_id, chunk_size}
morceau PUT /api/files/resumable/{upload_id}/chunk/{offset} <ct octets>
            ← 204
finaliser POST /api/files/resumable/{upload_id}/finalise {plain_blake3}
            ← 201 {file_id, url}
TTL sur inachevé : 24 h

files.h4_f:
liste_deny = {
  "application/x-dosexec",
  "application/x-sharedlib",
  "application/x-mach-binaire",
}
si magic.from_buffer(buf[:1024]) dans deny_list : renvoie 415

presence.h1_f:
client : à la première frappe → envoyer {type:"t", state:"start"}
         plus d'envoi pendant 3 s sauf si l'état change
         10 s après la dernière frappe → envoyer {type:"t", state:"stop"}
récepteur : arrêt automatique 10 s après le dernier "start" si aucun "stop" n'est arrivé

calls.h1_f:
POST /api/calls/{room_id}/start {vidéo, audio} → call_id
WS diffuser {type : "c", genre : "invite", call_id}
WS diffusion {type :"c", genre :"offre", sdp}
WS diffusion {type :"c", genre :"réponse", sdp}
WS diffusion {type :"c", genre :"candidat",ice} × N
POST /api/calls/{call_id}/end

federation.h2_f:
enveloppe = {
  noeud_source : hex32,
  utilisateur_cible : int64,
  inner_ciphertext : octets,
  inner_nonce : octets,
  envoyé_at : unix_ms,
}
sig = Ed25519Sign(source_priv, CBOR(enveloppe))
POST /federation/deliver { enveloppe, sig }

gossip.h3_f:
publicité = {pubkey, point de terminaison,adverted_at}
sig = Ed25519-Sign(pubkey_priv, CBOR(publicité))
Charge utile des potins : [..., {ad, sig}, ...]

récepteur : vérifier la signature par rapport à ad.pubkey → stocker iff ok
supplémentaire : PoW de 2 ^ 18 zéros non significatifs sur {pubkey, endpoint}

stealth.h2_f:
ClientHello octets = chrome_120_template avec {
  aléatoire = notre aléatoire,
  server_name = notre nom d'hôte (ou ECH-wrappé),
  session_id = notre identifiant de session,
}
JA4 = t13d_xxxx_xxxx_xxxx (correspond à la version stable actuelle de Chrome)

stealth.h4_f:
DoH : POST https://cloudflare-dns.com/dns-query {nom : x.vortexx.sol}
ECH : ClientHello.extensions +=crypted_sni(public_key_from_HTTPS_record)
DGA : domaine(t) = base32( SHA256(seed ∥ YYYY-MM-DD) )(:16] + ".example"

push.h4_f:
iOS NSE : didReceive(request) { décrypter(request.content.userInfo) }
Android FCM : onMessageReceived(remoteMessage) { décrypter(remoteMessage.data) }
Web SW : self.addEventListener('push', e => decrypt(e.data))

controller.h2_f:
outil = sign_tool
entrée = arborescence source, clés/release.key
manifeste = {
  version : "0.1.0",
  construit_at : unix_ms,
  fichiers : [{chemin, sha256, taille}, ...]
}
sig = Ed25519-Sign(release_priv, CBOR(manifeste))
sortie = INTEGRITY.sig.json = {manifeste, signé_by : pub_hex, sig : sig_hex}

bots.h1_f:
créer : POST /api/bots {nom d'utilisateur, nom_affichage, code}
          → {bot_id, jeton, clé publique}
run : en cours (coroutine à l'intérieur du nœud)
      OR externe (long-poll /api/bots/{id}/updates, token-auth'd)
message : {texte, signature : Ed25519-Sign(bot_priv, canonical_msg)}

bots.h2_f:
sur /start {
  émettre "Bienvenue, {ctx.first_name}"
}
sur /ajouter <élément> {
  state.list = (state.list ou []) + [ctx.args.item]
  émettre "Ajouté : {ctx.args.item}"
}

security.h4_f:
canary.txt (quotidiennement) :
  {date, signature : Ed25519-Sign(release_priv, date)}
le client vérifie → absent ou invalide ⇒ suspicion de compromission

urgence :
  admin POST /api/admin/revoke-all {raison}
  le nœud diffuse {type : "n", événement : "compromis", raison}
  les clients effacent les clés, forcent le redémarrage

debugging.h2_f:
histogrammes de taux (par itinéraire + méthode) :
  vortex_http_requests_total{route, méthode, statut}
  vortex_http_request_duration_seconds_bucket{route,méthode,le}

jauges Websocket :
  vortex_ws_connections{noeud}
  vortex_ws_fanout_queue_third{salle,utilisateur}

compteurs personnalisés :
  vortex_messages_sent_total{room_type}
  vortex_calls_started_total{genre}

